/** Render an icon. Decorative by default (hidden from assistive tech). */
function icon(string $name, string $class = 'icon'): string
{
    if (isset(ICONS_FILLED[$name])) {
        return '<svg class="' . e($class) . '" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">' . ICONS_FILLED[$name] . '</svg>';
    }

    return '<svg class="' . e($class) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . (ICONS[$name] ?? '') . '</svg>';
}
